import { ReactNode } from 'react';
import { cn } from './cn';

export interface NavItem {
  href: string;
  label: string;
  icon: ReactNode;
  /** contador exibido à direita, ex.: "17" em Conversas */
  count?: string | number;
  /** true deixa o contador na cor de aviso (ex.: Alertas pendentes) */
  countWarn?: boolean;
}

export interface SidebarProps {
  items: NavItem[];
  activeHref: string;
  /** nome + subtítulo do produto no topo (ex.: "VendCota" / "AI Sales OS") */
  brand: { icon: ReactNode; name: string; subtitle: string };
  /** rodapé: status do agente + conta do usuário */
  status: { label: string; description: string };
  account: { initials: string; name: string; role: string };
  renderLink?: (item: NavItem, isActive: boolean) => ReactNode;
}

/**
 * Navegação lateral fixa. É a MESMA em todas as telas — nunca reimplemente
 * por tela, apenas passe `activeHref` diferente.
 */
export function Sidebar({ items, activeHref, brand, status, account, renderLink }: SidebarProps) {
  return (
    <aside className="sticky top-0 flex h-screen w-[236px] flex-none flex-col border-r border-line bg-side p-3.5">
      <div className="mb-6 flex items-center gap-2.5 px-2.5 py-1">
        <div className="grid h-6 w-6 place-items-center rounded-[4px] bg-tx text-bg">{brand.icon}</div>
        <b className="text-md font-semibold tracking-tight text-tx">{brand.name}</b>
        <span className="text-sm text-tx3">{brand.subtitle}</span>
      </div>

      <nav className="flex flex-col gap-px">
        {items.map((item) => {
          const active = item.href === activeHref;
          const content = (
            <>
              <span className="h-4 w-4 flex-none [&>svg]:h-4 [&>svg]:w-4">{item.icon}</span>
              {item.label}
              {item.count !== undefined && (
                <span
                  className={cn(
                    'ml-auto font-mono text-xs',
                    item.countWarn ? 'text-warn' : 'text-tx3',
                  )}
                >
                  {item.count}
                </span>
              )}
            </>
          );
          if (renderLink) return <div key={item.href}>{renderLink(item, active)}</div>;
          return (
            <a
              key={item.href}
              href={item.href}
              className={cn(
                'flex items-center gap-2.5 rounded-ds px-2.5 py-1.5 text-base font-medium text-tx2 hover:bg-surface',
                active && 'bg-surface text-tx shadow-[inset_0_0_0_1px_var(--line)]',
              )}
            >
              {content}
            </a>
          );
        })}
      </nav>

      <div className="mt-auto border-t border-line pt-3.5">
        <div className="mb-1 flex items-center gap-2 text-base font-medium text-tx">
          <span className="h-1.5 w-1.5 flex-none rounded-full bg-ok" />
          {status.label}
        </div>
        <p className="text-sm leading-relaxed text-tx3">{status.description}</p>
        <div className="mt-4 flex items-center gap-2.5">
          <div className="grid h-6.5 w-6.5 flex-none place-items-center rounded-full bg-line text-xs font-semibold text-tx2">
            {account.initials}
          </div>
          <div>
            <b className="block text-sm font-medium text-tx">{account.name}</b>
            <span className="text-xs text-tx3">{account.role}</span>
          </div>
        </div>
      </div>
    </aside>
  );
}
